"use client"

import type React from "react"

import { useState } from "react"
import { Upload, X } from "lucide-react"
import { Button } from "@/components/ui/button"

interface ImageUploadProps {
  value: string
  onChange: (url: string) => void
  multiple?: boolean
}

export function ImageUpload({ value, onChange, multiple = false }: ImageUploadProps) {
  const [preview, setPreview] = useState(value)

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (file) {
      // In a real app, you would upload to your backend/storage here
      // For now, we'll create a local preview URL
      const url = URL.createObjectURL(file)
      setPreview(url)
      onChange(url)
    }
  }

  const handleRemove = () => {
    setPreview("")
    onChange("")
  }

  return (
    <div className="space-y-4">
      {preview ? (
        <div className="relative inline-block">
          <img
            src={preview || "/placeholder.svg"}
            alt="Upload preview"
            className="h-40 w-full object-cover rounded-lg border border-border"
          />
          <Button
            type="button"
            variant="destructive"
            size="icon"
            className="absolute top-2 right-2 h-8 w-8"
            onClick={handleRemove}
          >
            <X className="h-4 w-4" />
          </Button>
        </div>
      ) : (
        <label className="flex flex-col items-center justify-center h-40 w-full border-2 border-dashed border-border rounded-lg cursor-pointer hover:bg-accent/50 transition-colors">
          <Upload className="h-8 w-8 text-muted-foreground mb-2" />
          <span className="text-sm text-muted-foreground">Click to upload image</span>
          <span className="text-xs text-muted-foreground mt-1">PNG, JPG up to 10MB</span>
          <input type="file" className="hidden" accept="image/*" multiple={multiple} onChange={handleFileChange} />
        </label>
      )}
      <p className="text-xs text-muted-foreground">
        Note: In production, images will be uploaded to your storage service
      </p>
    </div>
  )
}
